const source = (paragraph: number): SourceRef => ({ documentId: 'word-18-10', paragraph });
const slugify = (value: string) => value.normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

function toParagraph(slug: SegmentSlug, value: RawParagraph): EditorialParagraph {
  return { id: `${slug}-${slugify(value.anchorId ?? value.text.slice(0, 44))}-${value.paragraph}`, text: value.text, sourceParagraphs: [], originRefs: [source(value.paragraph), ...(value.extraOrigins ?? []).map(source)], kind: value.kind, ...(value.anchorId ? { anchorId: value.anchorId } : {}) };
}

function toBlocks(slug: SegmentSlug, entries: readonly EditorialParagraph[]): SegmentBlock[] {
  const blocks: SegmentBlock[] = [];
  let current: { id: string; title: string; paragraphs: EditorialParagraph[] } | undefined;
  for (const entry of entries) {
    if (entry.kind === 'heading') {
      current = { id: entry.anchorId ?? `${slug}-${slugify(entry.text)}`, title: entry.text, paragraphs: [entry] };
      blocks.push(current);
      continue;
    }
    if (!current) { current = { id: `${slug}-detalhes`, title: 'Detalhes da solução', paragraphs: [] }; blocks.push(current); }
    current.paragraphs.push(entry);
  }
  return blocks;
}

export const segmentsContent: readonly SegmentContent[] = definitions.map((definition) => {
  const entries = rawParagraphs[definition.slug];
  const introduction = definition.introSources.map((paragraph) => entries.find((entry) => entry.paragraph === paragraph)).filter((entry): entry is RawParagraph => Boolean(entry)).map((entry) => toParagraph(definition.slug, entry));
  const introSources = new Set<number>(definition.introSources);
  const details = entries.filter((entry) => !introSources.has(entry.paragraph)).map((entry) => toParagraph(definition.slug, entry));
  const pageRefs = [source(definition.titleSource), ...entries.map((entry) => source(entry.paragraph)), ...entries.flatMap((entry) => (entry.extraOrigins ?? []).map(source))];
  return { slug: definition.slug, title: definition.title, homeSummary: definition.homeSummary, introduction, blocks: toBlocks(definition.slug, details), originRefs: pageRefs };
});

export function getSegment(slug: string): SegmentContent | undefined {
  return segmentsContent.find((segment) => segment.slug === slug);
}
